text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已完成任务工时总和Top2项目",
      "business_question": "按项目汇总已完成任务的工时总和，并降序取前两名？（约束：只看已完成任务；指标为工时总和；限制为降序取前两名）",
      "priority": "P0",
      "priority_reason": "直接回答核心分析目标。删除此任务将无法获得任何关于项目工时分布的结论，无法支持资源分配或绩效评估决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours_sum"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "top_n",
          "params": {
            "field": "total_hours_sum",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
